#!/usr/bin/env bash
# Render the README images from docs/img/src/*.html with headless Chrome.
#
#   scripts/render-images.sh            # all images
#   scripts/render-images.sh banner     # just one
#
# Each source is a self-contained HTML page (inline CSS/SVG, Google Fonts).
# `?theme=dark` switches it to the dark tokens. Output: docs/img/<name>-light.png
# and docs/img/<name>-dark.png at 2x (console is always dark: docs/img/console.png).
# i2c.html is generated by docs/img/src/make_i2c.py from a sigrok capture.
# `app` is the real player app (always dark: docs/img/app.png): the repo root is
# served on localhost:8012 and app-seed.html seeds its progress, then opens it.
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
SRC="$ROOT/docs/img/src"
OUT="$ROOT/docs/img"
CHROME="${CHROME:-/usr/bin/google-chrome}"

# name  width  height  themes
IMAGES=(
  "banner  1280 420 light,dark"
  "console 1100 810 single"
  "app     1440 900 served"
  "tracks  1200 468 light,dark"
  "modes   1200 602 light,dark"
  "i2c     1200 360 light,dark"
)

shot() { # src-url out.png w h
  "$CHROME" --headless=new --hide-scrollbars --force-device-scale-factor=2 \
    --window-size="$3,$4" --virtual-time-budget=3000 \
    --screenshot="$2" "$1" >/dev/null 2>&1
  if command -v pngquant >/dev/null; then
    pngquant --force --skip-if-larger --quality=80-98 --output "$2" -- "$2" || true
  elif command -v optipng >/dev/null; then
    optipng -quiet -o2 "$2"
  fi
  printf '%-28s %6d KB\n' "${2#$ROOT/}" $(( $(stat -c %s "$2") / 1024 ))
}

for spec in "${IMAGES[@]}"; do
  read -r name w h themes <<<"$spec"
  if [ $# -gt 0 ] && [[ " $* " != *" $name "* ]]; then continue; fi
  [ "$themes" = served ] || [ -f "$SRC/$name.html" ] || { echo "missing $SRC/$name.html" >&2; exit 1; }
  if [ "$themes" = served ]; then
    [ -f "$SRC/$name-seed.html" ] || { echo "missing $SRC/$name-seed.html" >&2; exit 1; }
    python3 -m http.server -b 127.0.0.1 -d "$ROOT" 8012 >/dev/null 2>&1 &
    srv=$!
    sleep 1
    shot "http://localhost:8012/docs/img/src/$name-seed.html?mac=240AC4123456&sel=BLE-03" "$OUT/$name.png" "$w" "$h"
    kill "$srv"
    continue
  fi
  url="file://$SRC/$name.html"
  if [ "$themes" = single ]; then
    shot "$url" "$OUT/$name.png" "$w" "$h"
  else
    shot "$url" "$OUT/$name-light.png" "$w" "$h"
    shot "$url?theme=dark" "$OUT/$name-dark.png" "$w" "$h"
  fi
done
